questions.solution:
function parsePositive(text) {
  const n = Number(text);
  if (!Number.isInteger(n) || n <= 0) {
    throw new Error("positive integer required");
  }
  return n;
}

function demoReturn() {
  try {
    return 1;
  } finally {
    return 2;
  }
}

function messageOf(fn) {
  try {
    fn();
    return "ok";
  } catch (err) {
    return err.message;
  }
}
